<script setup>
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useMovies} from '../composables/useMovies.js';import {filterMovies} from '../utils/catalog.js';import MovieCard from '../components/MovieCard.vue';import SearchBar from '../components/SearchBar.vue';import GenreFilter from '../components/GenreFilter.vue';import AppIcon from '../components/AppIcon.vue';
const props=defineProps({favoritesOnly:{type:Boolean,default:false}});const {movies,loading,error,favoriteIds,loadMovies}=useMovies();const route=useRoute(),router=useRouter();const search=ref(String(route.query.q||'')),genre=ref(String(route.query.genre||'All films')),sort=ref(['rating','year','title'].includes(route.query.sort)?route.query.sort:'rating');const genres=computed(()=>['All films',...new Set(movies.value.map(m=>m.genre))]);const filtered=computed(()=>filterMovies(movies.value,{search:search.value,genre:genre.value,sort:sort.value,favoritesOnly:props.favoritesOnly,favoriteIds:favoriteIds.value}));const base=import.meta.env.BASE_URL;
watch([search,genre,sort],()=>router.replace({path:route.path,query:{...(search.value?{q:search.value}:{}),...(genre.value!=='All films'?{genre:genre.value}:{}),...(sort.value!=='rating'?{sort:sort.value}:{})}}));watch(()=>route.path,()=>{search.value='';genre.value='All films';sort.value='rating';});
function reset(){search.value='';genre.value='All films';sort.value='rating';}
</script>
<template><section v-if="!favoritesOnly" class="hero"><img class="hero-art" :src="base+'posters/hero.svg'" alt="Original illustration of a distant sun above a desert landscape"><div class="hero-shade"></div><div class="hero-content"><div class="eyebrow"><span class="tiny-line"></span>THE WORLD IS FULL OF STORIES.</div><h1>Find your next<br><em>favorite.</em></h1><p>For the nights you want to feel something.<br>Discover a film that stays with you.</p><a href="#collection" class="button amber">Explore the collection<AppIcon name="arrow"/></a><div class="hero-bottom"><span class="hero-index">01 <i>/</i> 12</span><span class="hero-feature"><small>IN THE SPOTLIGHT</small>Beyond the Quiet <span>2025 · Sci-Fi</span></span><RouterLink to="/movie/1" aria-label="Explore Beyond the Quiet" class="round-link"><AppIcon name="arrow"/></RouterLink></div></div><span class="hero-side">CURATED FOR THE CURIOUS.</span></section><section v-else class="watchlist-heading"><span class="eyebrow">SAVED FOR ANOTHER NIGHT</span><h1>Your next <em>movie night.</em></h1><p>All the stories you don’t want to forget, in one place.</p><span class="watchlist-count"><AppIcon name="bookmark"/>{{favoriteIds.length}} films on your watchlist</span></section><section id="collection" class="collection"><div class="collection-heading"><div><span class="eyebrow">{{favoritesOnly?'YOUR PERSONAL COLLECTION':'LESS SCROLLING. MORE DISCOVERING.'}}</span><h2>{{favoritesOnly?'The watchlist.':'Worth your time.'}}<span>{{filtered.length.toString().padStart(2,'0')}}</span></h2></div><SearchBar v-model="search"/></div><div class="collection-toolbar"><GenreFilter v-model="genre" :genres="genres"/><label class="sort-control">Sort by <select v-model="sort" aria-label="Sort films"><option value="rating">Top rated</option><option value="year">Newest first</option><option value="title">Title A–Z</option></select></label></div><div v-if="loading" class="movie-grid" aria-live="polite" aria-label="Loading films"><div v-for="i in 4" class="skeleton-card"><div></div><p></p></div></div><div v-else-if="error" class="empty-state" role="alert"><AppIcon name="film"/><h2>A brief intermission.</h2><p>{{error}}</p><button class="button amber" @click="loadMovies"><AppIcon name="refresh"/>Try again</button></div><div v-else-if="!filtered.length" class="empty-state"><AppIcon :name="favoritesOnly?'bookmark':'search'"/><h2>{{favoritesOnly&&!favoriteIds.length?'Your watchlist starts here.':'No films in this scene.'}}</h2><p>{{favoritesOnly&&!favoriteIds.length?'Save a film using the bookmark on its poster.':'Try another title or clear your genre filter.'}}</p><RouterLink v-if="favoritesOnly&&!favoriteIds.length" to="/" class="button amber">Discover films<AppIcon name="arrow"/></RouterLink><button v-else class="button" @click="reset">Clear filters</button></div><div v-else class="movie-grid"><MovieCard v-for="movie in filtered" :key="movie.id" :movie="movie"/></div><div v-if="!loading&&!error" class="collection-foot"><span>{{filtered.length}} {{filtered.length===1?'story':'stories'}} waiting to be discovered.</span><span><i></i>Original concept collection · Demo ratings</span></div></section><section v-if="!favoritesOnly" class="editorial"><div class="editorial-symbol">✳</div><div><span class="eyebrow">PICK SOMETHING UNEXPECTED.</span><h2>Different stories.<br><em>A different perspective.</em></h2></div><p>A quiet drama. A distant world. A journey you didn’t see coming. Sometimes the best film is the one you almost skipped.</p></section></template>
